    jsonb_build_object('kind', 'contra', 'subject', 'Mockaquine', 'text', 'Mockaquine אסורה בהיריון.', 'anchor', 3, 'quote', 'Mockaquine אסורה', 'slides', jsonb_build_array(8), 'red_flag', true, 'weight', 3)),
