select 'K6. history: ' || count(*) || ' row, author Noa: ' || bool_and(author_id = 'cccccccc-0000-4000-8000-000000000003') || ', kind ' || min(kind) || ', anchor ' || min(anchor) || ', gen ' || min(gen) || ', note kept: ' || bool_and(note <> '')
