exception when others then raise notice 'V1b. %: a stranger opens none (%)', case when sqlerrm = 'forbidden' then 'ok' else 'FAIL' end, sqlerrm; end $$;
do $$ begin perform public.study_dispute_state(current_setting('t.d1')::uuid);
