exception when others then raise notice 'GS1e. %: a stale version (%)', case when sqlerrm = 'conflict' then 'ok' else 'FAIL' end, sqlerrm; end $$;
set request.jwt.claim.sub = 'd6000000-0000-4000-8000-000000000009';   -- not a member
