  || ' · ' || stest.err(format('select public.study_exam_save_items(%L, %L, %L, 0, %L)', :'sj1', gen_random_uuid(), '[]', :'skey'))
  || ' · ' || stest.err(format('select public.study_exam_save_items(%L, %L, %L, 0)', :'sj1', :'sl_1', '[]')),
  '4 0 1 · lease lost · forbidden');
