set role authenticated;
-- The opener's own session ended: no code for anyone.
reset role; delete from auth.sessions where id = '29000000-0000-4000-8000-000000000001'; set role authenticated;
do $$ begin perform public.study_code_issue('19000000-0000-4000-8000-0000000000a1', '19000000-0000-4000-8000-000000000005'); raise notice 'I5e. FAIL';
exception when others then raise notice 'I5e. %: an ended session of the opener makes no code (%)', case when sqlerrm = 'session ended' then 'ok' else 'FAIL' end, sqlerrm; end $$;
reset role; insert into auth.sessions (id, user_id) values ('29000000-0000-4000-8000-000000000001', '19000000-0000-4000-8000-000000000001'); set role authenticated;

-- The server's call, as the anon key.
reset role; reset request.jwt.claim.sub; set role anon;
do $$ begin perform public.study_code_redeem('AAAA-AAAA-AAAA-AAAA', '1.1.1.1', 'wrong-key'); raise notice 'I6. FAIL: redeemed without the server key';
exception when others then raise notice 'I6. %: no server key, no redeem (%)', case when sqlerrm = 'forbidden' then 'ok' else 'FAIL' end, sqlerrm; end $$;
select 'I7. ' || case when public.study_code_redeem('AAAA-AAAA-AAAA-AAAA', '1.1.1.1', :'ikey') ->> 'error' = 'code not found' then 'ok' else 'FAIL' end || ': a wrong code is "code not found"';
reset role;
select 'I7b. ' || case when count(*) = 1 then 'ok' else 'FAIL' end || ': and its try stays counted (' || count(*) || ')' from study_private.code_tries where not ok;
select 'I7c. ' || case when count(*) = 0 then 'ok' else 'FAIL' end || ': no code is stored as text'
  from study_private.member_codes c where position(replace(:'dana_code', '-', '') in encode(c.code_hash, 'escape')) > 0;
select 'I7d. ' || case when count(*) = 1 and bool_and(ip !~ '1\.1\.1\.1')
                          and bool_and(ip <> encode(sha256(convert_to('tamtzit-ip:1.1.1.1', 'UTF8')), 'hex'))
  then 'ok' else 'FAIL' end || ': the address is kept only as a hash, keyed with the server key'
  from study_private.code_tries;
set role anon;
select public.study_code_redeem(lower(replace(:'dana_code', '-', ' ')), '1.1.1.1', :'ikey') as r \gset
reset role;
select 'I8. ' || case when (:'r')::jsonb ? 'password' then 'ok' else 'FAIL ' || :'r' end || ': lower case with spaces opens it';
select 'I8b. ' || case when u.encrypted_password = extensions.crypt((:'r')::jsonb ->> 'password', u.encrypted_password)
                         and u.encrypted_password like '$2a$10$%' and u.email_confirmed_at is not null and u.is_anonymous
                         and u.email = (:'r')::jsonb ->> 'email'
  then 'ok' else 'FAIL' end || ': Dana''s own user: bcrypt $2a$10$ of the one-time password, confirmed, still anonymous'
  from auth.users u where u.id = '19000000-0000-4000-8000-000000000002';
-- GoTrue's own lookup (models.FindUserByEmailAndAudience): exactly this user.
select 'I8c. ' || case when count(*) = 1 and min(id::text) = '19000000-0000-4000-8000-000000000002' then 'ok' else 'FAIL' end || ': Auth''s lookup finds Dana'
  from auth.users where instance_id = '00000000-0000-0000-0000-000000000000' and lower(email) = lower((:'r')::jsonb ->> 'email')
   and aud = 'authenticated' and is_sso_user = false;
-- Someone with a session asks Auth for an email change in the 3 minutes (stand-in for GoTrue's columns).
update auth.users set email_change = 'evil@example.com', email_change_token_new = 'tok' where id = '19000000-0000-4000-8000-000000000002';
insert into auth.one_time_tokens (user_id, token_type, token_hash) values ('19000000-0000-4000-8000-000000000002', 'email_change_token_new', 'tok');
-- A second device redeems inside the 3 minutes: the "before" stays the member's own.
set role anon;
select public.study_code_redeem(:'dana_code', '2.2.2.2', :'ikey') as r2 \gset
reset role;
select 'I8d. ' || case when (:'r2')::jsonb ->> 'email' <> (:'r')::jsonb ->> 'email' and p.prev_pw = '' and p.prev_email is null
  then 'ok' else 'FAIL' end || ': a second redeem gets new values; the first "before" is kept'
  from study_private.code_pending p where p.user_id = '19000000-0000-4000-8000-000000000002';
set role authenticated; set request.jwt.claim.sub = '19000000-0000-4000-8000-000000000002'; set request.jwt.claims = '{"session_id":"29000000-0000-4000-8000-000000000002"}';
select public.study_code_finish();
reset role;
select 'I9. ' || case when email is null and encrypted_password = '' and email_confirmed_at is null and is_anonymous
                        and email_change = '' and email_change_token_new = ''
  then 'ok' else 'FAIL' end || ': finish puts Dana back (no address, no password, no email change waiting)'
  from auth.users where id = '19000000-0000-4000-8000-000000000002';
select 'I9b. ' || case when not exists (select 1 from auth.one_time_tokens where user_id = '19000000-0000-4000-8000-000000000002')
  and not exists (select 1 from study_private.code_pending) then 'ok' else 'FAIL' end || ': no one-time token, nothing pending';
select 'I9c. ' || case when uses = 2 and used_at is not null then 'ok' else 'FAIL' end || ': two uses recorded'
  from study_private.member_codes where user_id = '19000000-0000-4000-8000-000000000002';

-- A device that never finishes: put back after 3 minutes.
set role anon;
select public.study_code_redeem(:'dana_code', '1.1.1.1', :'ikey') is not null as x \gset
reset role;
update study_private.code_pending set until = now() - interval '1 second';
select 'I10. ' || case when study_private.code_restore() = 1 then 'ok' else 'FAIL' end || ': the sweep puts back what is over 3 minutes';
select 'I10b. ' || case when email is null and encrypted_password = '' then 'ok' else 'FAIL' end || ': Dana is back to no address, no password'
  from auth.users where id = '19000000-0000-4000-8000-000000000002';
select 'I10c. ' || case when count(*) = 1 then 'ok' else 'FAIL' end || ': pg_cron runs it every 5 minutes'
  from cron.job where jobname = 'study-code-restore' and schedule = '*/5 * * * *';

-- A new code: the old one stops at once.
set role authenticated; set request.jwt.claim.sub = '19000000-0000-4000-8000-000000000002'; set request.jwt.claims = '{"session_id":"29000000-0000-4000-8000-000000000002"}';
select public.study_code_new() as dana_code2 \gset
reset role; set role anon;
select 'I11. ' || case when public.study_code_redeem(:'dana_code', '1.1.1.1', :'ikey') ->> 'error' = 'code not found' then 'ok' else 'FAIL' end || ': the old code no longer opens';
reset role;
select study_private.code_restore();

-- The opener makes a new code for Dana: Dana is told, by name, once.
set role authenticated; set request.jwt.claim.sub = '19000000-0000-4000-8000-000000000001'; set request.jwt.claims = '{"session_id":"29000000-0000-4000-8000-000000000001"}';
select public.study_code_issue('19000000-0000-4000-8000-0000000000a1', '19000000-0000-4000-8000-000000000002') as dana_code3 \gset
set request.jwt.claim.sub = '19000000-0000-4000-8000-000000000002'; set request.jwt.claims = '{"session_id":"29000000-0000-4000-8000-000000000002"}';
select 'I12. ' || case when s.by_opener and s.notice and s.by_name = 'פותחת' and s.replaced and s.uses = 0 then 'ok' else 'FAIL' end
  || ': Dana sees that the opener made it, in place of her code'
  from public.study_code_status() s;
select public.study_code_seen();
select 'I12b. ' || case when s.by_opener and not s.notice then 'ok' else 'FAIL' end || ': once seen, the notice goes' from public.study_code_status() s;
reset role; set role anon;
select 'I12c. ' || case when public.study_code_redeem(:'dana_code2', '1.1.1.1', :'ikey') ->> 'error' = 'code not found'
                          and public.study_code_redeem(:'dana_code3', '1.1.1.1', :'ikey') ? 'password'
  then 'ok' else 'FAIL' end || ': the code before it dies, the opener''s works';
reset role;
select study_private.code_restore('19000000-0000-4000-8000-000000000002');
set role authenticated; set request.jwt.claim.sub = '19000000-0000-4000-8000-000000000002'; set request.jwt.claims = '{"session_id":"29000000-0000-4000-8000-000000000002"}';
select 'I12e. ' || case when s.uses = 1 and s.used_at is not null then 'ok' else 'FAIL' end || ': and that the opener''s code already brought a device in'
  from public.study_code_status() s;
reset role;
select 'I12d. ' || string_agg(event, ',' order by id) from study_private.code_log where user_id = '19000000-0000-4000-8000-000000000002';

-- The limits: 10 wrong tries from one address in 15 minutes, 100 in all per hour.
delete from study_private.code_tries;
set role anon;
select count(*) from (select public.study_code_redeem('BBBB-BBBB-BBBB-BBBB', '3.3.3.3', :'ikey') from generate_series(1, 10)) s \gset
select 'I13. ' || case when public.study_code_redeem(:'dana_code3', '3.3.3.3', :'ikey') ->> 'error' = 'too many tries' then 'ok' else 'FAIL' end
  || ': the 11th try from one address is refused, even with the right code';
select 'I13b. ' || case when public.study_code_redeem(:'dana_code3', '4.4.4.4', :'ikey') ? 'password' then 'ok' else 'FAIL' end
  || ': another address still gets in';
reset role;
select study_private.code_restore('19000000-0000-4000-8000-000000000002');
update study_private.code_tries set at = now() - interval '20 minutes';
set role anon;
select count(*) from (select public.study_code_redeem('CCCC-CCCC-CCCC-CCCC', '5.5.' || (g / 200) || '.' || (g % 200), :'ikey') from generate_series(1, 899) g) s \gset
select 'I13c. ' || case when public.study_code_redeem(:'dana_code3', '6.6.6.6', :'ikey') ? 'password' then 'ok' else 'FAIL' end
  || ': 909 wrong tries in an hour from many addresses still let a member in';
reset role;
select study_private.code_restore('19000000-0000-4000-8000-000000000002');
set role anon;
select count(*) from (select public.study_code_redeem('CCCC-CCCC-CCCC-CCCC', '8.8.' || (g / 200) || '.' || (g % 200), :'ikey') from generate_series(1, 91) g) s \gset
select 'I13e. ' || case when public.study_code_redeem(:'dana_code3', '6.6.6.7', :'ikey') ->> 'error' = 'too many tries' then 'ok' else 'FAIL' end
  || ': 1000 wrong tries in an hour close it for everyone (the backstop)';
reset role;
delete from study_private.code_tries;
select 'I13d. ' || case when (public.study_code_redeem('', '7.7.7.7', :'ikey') ->> 'error') = 'code not found'
                          and (public.study_code_redeem(null, '7.7.7.7', :'ikey') ->> 'error') = 'code not found'
  then 'ok' else 'FAIL' end || ': empty or missing input is a wrong code, not an error';
delete from study_private.code_tries;

-- A one-time address left on the user (a sweep that raced a redeem, before
-- the lock) is never taken for the member's own "before".
update auth.users set email = 'c-0123@code.tamtzit.invalid', encrypted_password = '$2a$10$leftoverleftoverleftoverleftoverleftoverleftoverleft',
                      email_confirmed_at = now() where id = '19000000-0000-4000-8000-000000000002';
set role anon;
select public.study_code_redeem(:'dana_code3', '9.9.9.9', :'ikey') ? 'password' as x \gset
reset role;
select 'I19. ' || case when p.prev_email is null and p.prev_pw = '' and p.prev_conf is null then 'ok' else 'FAIL' end
  || ': a leftover one-time address is no "before"' from study_private.code_pending p where p.user_id = '19000000-0000-4000-8000-000000000002';
select study_private.code_restore('19000000-0000-4000-8000-000000000002');
select 'I19b. ' || case when email is null and encrypted_password = '' and email_confirmed_at is null then 'ok' else 'FAIL' end
  || ': and the user ends with no address and no password' from auth.users where id = '19000000-0000-4000-8000-000000000002';
select 'I19c. ' || case when not exists (select 1 from study_private.code_pending where prev_email like 'c-%@code.tamtzit.invalid')
  then 'ok' else 'FAIL' end || ': no pending row keeps a one-time address as "before"';
delete from study_private.code_tries;

-- "שמור" now says "has a code".
set role authenticated; set request.jwt.claim.sub = '19000000-0000-4000-8000-000000000001'; set request.jwt.claims = '{"session_id":"29000000-0000-4000-8000-000000000001"}';
select 'I14. ' || string_agg(m.name || '=' || s.saved, ', ' order by m.name)
  from public.study_member_saved('19000000-0000-4000-8000-0000000000a1') s join public.study_members m on m.user_id = s.user_id and m.group_id = '19000000-0000-4000-8000-0000000000a1';

-- Removed from the group: the code goes with the membership.
select public.study_remove_member('19000000-0000-4000-8000-0000000000a1', '19000000-0000-4000-8000-000000000002');
reset role; set role anon;
select 'I15. ' || case when public.study_code_redeem(:'dana_code3', '1.1.1.1', :'ikey') ->> 'error' = 'code not found' then 'ok' else 'FAIL' end
  || ': a removed member''s code no longer opens';
reset role;
select 'I15b. ' || case when not exists (select 1 from study_private.member_codes where user_id = '19000000-0000-4000-8000-000000000002')
  then 'ok' else 'FAIL' end || ': and is gone';

-- The switch: off stops new codes and redeems; on again, all as before.
delete from study_private.code_tries;
insert into study_private.features (name, enabled) values ('codes', false)
on conflict (name) do update set enabled = excluded.enabled;
select 'I15c. ' || case when public.study_code_redeem('AAAA-AAAA-AAAA-AAAA', '1.1.1.1', :'ikey') ->> 'error' = 'codes off'
  and not exists (select 1 from study_private.code_tries) then 'ok' else 'FAIL' end || ': switched off, a redeem is "codes off" and counts no try';
set role authenticated; set request.jwt.claim.sub = '19000000-0000-4000-8000-000000000005'; set request.jwt.claims = '{"session_id":"29000000-0000-4000-8000-000000000005"}';
do $$ begin perform public.study_code_new(); raise notice 'I15d. FAIL: a code while switched off';
exception when others then raise notice 'I15d. %: no new code while switched off (%)', case when sqlerrm = 'off' then 'ok' else 'FAIL' end, sqlerrm; end $$;
reset role;
delete from study_private.features where name = 'codes';

-- Who may call what.
select 'I16. ' || case when has_function_privilege('anon', 'public.study_code_redeem(text, text, text)', 'execute')
  and not has_function_privilege('anon', 'public.study_code_new()', 'execute')
  and not has_function_privilege('anon', 'public.study_code_issue(uuid, uuid)', 'execute')
  and not has_function_privilege('anon', 'public.study_code_status()', 'execute')
  and not has_function_privilege('authenticated', 'public.study_code_redeem(text, text, text)', 'execute')
  and not has_function_privilege('authenticated', 'study_private.code_set(uuid, uuid)', 'execute')
  then 'ok' else 'FAIL' end || ': anon only redeems (with the server key); members never redeem directly';
select 'I17. ' || case when public.study_schema() ->> 'I' = '1' then 'ok' else 'FAIL' end || ': the registry has I 1';

-- The fixtures go.
delete from study_private.code_log where user_id::text like '19000000-%';
delete from study_private.code_tries;
delete from public.study_groups where id = '19000000-0000-4000-8000-0000000000a1';
delete from auth.sessions where id::text like '29000000-%';
delete from auth.users where id::text like '19000000-%';
-- ════ END SECTION I ════

-- ════ BEGIN SECTION R ════ (checks for supabase/tests/study.sql)
-- Notifications and the inbox (R 1 and R 2): who sees which rows, the
-- devices, the hooks, coalescing, the claim's decisions (off, none, held, capped, quiet,
-- nosub), the worker's report, the minute job's sign-in scan, the kick and
-- its breaker, seen, and loading the section twice. All titles are invented.
-- (Giving up on a lock after 200 ms needs two sessions: notify-concurrency.sh.)
\set ON_ERROR_STOP 1
\pset tuples_only on
reset role;
create or replace function pg_temp.rok(p_name text, p_ok boolean, p_what text) returns text language sql as $$
  select p_name || '. ' || case when coalesce(p_ok, false) then 'ok' else 'FAIL' end || ': ' || p_what $$;
insert into vault.decrypted_secrets (name, decrypted_secret) values
  ('study_worker_key', 'k-0123456789abcdef0123456789abcdef'),
  ('study_site_url', 'https://tamtzit.vercel.app')
on conflict (name) do update set decrypted_secret = excluded.decrypted_secret;
\set rkey 'k-0123456789abcdef0123456789abcdef'
\set ru1 '1a000000-0000-4000-8000-000000000001'
\set ru2 '1a000000-0000-4000-8000-000000000002'
\set ru3 '1a000000-0000-4000-8000-000000000003'
\set ru4 '1a000000-0000-4000-8000-000000000004'
\set ru5 '1a000000-0000-4000-8000-000000000005'
\set rg '1a000000-0000-4000-8000-0000000000a1'
\set rl1 '1a000000-0000-4000-8000-0000000000b1'
\set rl2 '1a000000-0000-4000-8000-0000000000b2'
insert into auth.users (id, raw_user_meta_data) values
 (:'ru1', '{"app":"study","full_name":"אלה"}'), (:'ru2', '{"app":"study","full_name":"בני"}'),
 (:'ru3', '{"app":"study","full_name":"גל"}'), (:'ru4', '{"app":"study","full_name":"דור"}'),
 (:'ru5', '{"app":"study","full_name":"הדר"}');
insert into public.study_groups (id, name, join_code, created_by) values (:'rg', 'קבוצת ההתראות', 'RNOTE1', :'ru1');
insert into public.study_members (group_id, user_id, name) values
 (:'rg', :'ru1', 'אלה'), (:'rg', :'ru2', 'בני'), (:'rg', :'ru3', 'גל'), (:'rg', :'ru5', 'הדר');
insert into public.study_lectures (id, group_id, title, source_kind, slides, created_by) values
 (:'rl1', :'rg', 'הרצאה בדויה על Invented Kinetics', 'pptx', '[]', :'ru1'),
 (:'rl2', :'rg', 'הרצאה בדויה שנייה', 'pptx', '[]', :'ru2');
-- Every check below is about one rule at a time: no night, no Shabbat, unless a check sets them.
insert into public.study_notify_prefs (user_id, quiet) values (:'ru1', false), (:'ru2', false), (:'ru3', false);

-- ── The section, its switches and loading it twice ──
select pg_temp.rok('R1', public.study_schema() ->> 'R' = '2', 'the registry has R 2');
select pg_temp.rok('R1b', (select bool_and(case name when 'notify' then not enabled else enabled end) and count(*) = 2
                             from study_private.features where name in ('notify', 'notify_hooks')),
  'the switches: notify inserted off, notify_hooks on');
select pg_temp.rok('R1c',
  (select count(*) from pg_policies where tablename in ('study_notices', 'study_notify_prefs', 'study_push_subs')) = 2
  and (select count(*) from pg_trigger where tgname like 'study\_r\_%' and not tgisinternal) = 12
  and (select count(*) from cron.job where jobname = 'study-notify' and schedule = '* * * * *') = 1
  and (select count(*) from cron.job where jobname = 'study-notify-clean' and schedule = '41 3 * * *') = 1
  and (select count(*) from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'study_notices') = 1
  and (select count(*) from study_private.notice_kinds where kind <> 'set_solved') = 25   -- section L registers set_solved
  and (select count(*) from study_private.notify_kick) = 1,
  'loaded twice: one policy each, twelve hooks, two jobs, published once, 25 kinds, one kick row');
select pg_temp.rok('R1d', (select count(*) from pg_publication_tables where pubname = 'supabase_realtime'
                            and tablename in ('study_push_subs', 'study_notify_prefs')) = 0,
  'devices and settings are never published');
select pg_temp.rok('R1e', (select string_agg(kind || ':' || cat || ':' || push, ',' order by kind) from study_private.notice_kinds
                            where kind in ('set_shared', 'similar_ready', 'lab_new')) = 'lab_new:inapp:false,set_shared:mine:true,similar_ready:mine:true',
  'the kinds of packages not built yet are reserved');

-- ── The defaults, in one place ──
insert into public.study_notify_prefs (user_id) values (:'ru4');
select pg_temp.rok('R2', (to_jsonb(study_private.notify_prefs_of(:'ru5')) - 'user_id' - 'updated_at')
                         = (select to_jsonb(p) - 'user_id' - 'updated_at' from public.study_notify_prefs p where p.user_id = :'ru4'),
  'no row reads exactly as the column defaults (live, mine on; reminder off at 19:30; nights 23:00-07:30; no Shabbat)');
delete from public.study_notify_prefs where user_id = :'ru4';

-- ── Who may read and call what ──
select pg_temp.rok('R3', (select bool_and(c.relrowsecurity) from pg_class c
                           where c.oid in ('public.study_push_subs'::regclass, 'public.study_notify_prefs'::regclass, 'public.study_notices'::regclass))
  and not has_table_privilege('authenticated', 'public.study_push_subs', 'select')
  and not has_table_privilege('anon', 'public.study_notices', 'select')
  and not has_table_privilege('authenticated', 'public.study_notices', 'insert')
  and not has_table_privilege('authenticated', 'public.study_notices', 'update')
  and not has_table_privilege('authenticated', 'public.study_notify_prefs', 'update')
  and not has_schema_privilege('authenticated', 'study_private', 'usage'),
  'row security on; nobody reads devices; members only read their rows, and write none directly');
select pg_temp.rok('R3b',
  not has_function_privilege('anon', 'public.study_push_subscribe(text, text, text, text, text, text)', 'execute')
  and not has_function_privilege('anon', 'public.study_notices_mine(uuid, bigint, int)', 'execute')
  and not has_function_privilege('anon', 'public.study_notify_test()', 'execute')
  and not has_function_privilege('anon', 'public.study_quiz_quiet(uuid)', 'execute')
  and has_function_privilege('authenticated', 'public.study_notices_seen(uuid, bigint[])', 'execute')
  and not has_function_privilege('authenticated', 'study_private.notice_add(uuid, uuid, text, jsonb, jsonb, text, text, uuid, timestamptz)', 'execute'),
  'the member RPCs are signed-in only; notice_add is nobody''s to call');
set role authenticated; set request.jwt.claim.sub = :'ru4';
do $$ begin perform public.study_notify_state(); raise notice 'R3c. FAIL: a signed-in stranger read the state';
exception when others then raise notice 'R3c. %: a signed-in stranger is refused (%)', case when sqlerrm = 'forbidden' then 'ok' else 'FAIL' end, sqlerrm; end $$;
do $$ begin perform public.study_push_subscribe('https://fcm.googleapis.com/fcm/send/r-stranger', 'B' || repeat('p', 86), repeat('a', 22), 'kid12345');
  raise notice 'R3d. FAIL: a stranger subscribed';
exception when others then raise notice 'R3d. %: a stranger cannot add a device (%)', case when sqlerrm = 'forbidden' then 'ok' else 'FAIL' end, sqlerrm; end $$;
reset role;

-- ── Devices ──
select pg_temp.rok('R4', study_private.push_host_ok('https://fcm.googleapis.com/fcm/send/abc123')
  and study_private.push_host_ok('https://updates.push.services.mozilla.com/wpush/v2/abc')
  and study_private.push_host_ok('https://web.push.apple.com/QAbcdefgh123')
  and study_private.push_host_ok('https://api.push.apple.com/3/device/abc')
  and study_private.push_host_ok('https://wns2-par02p.notify.windows.com/w/?token=BQYAAAB'),
  'the five kinds of push service are accepted');
select pg_temp.rok('R4b', not (study_private.push_host_ok('http://fcm.googleapis.com/fcm/send/abc123')
  or study_private.push_host_ok('https://evil.com/fcm/send/abc12345678')
  or study_private.push_host_ok('https://fcm.googleapis.com.evil.com/fcm/send/abc')
  or study_private.push_host_ok('https://user@fcm.googleapis.com/fcm/send/abc')
  or study_private.push_host_ok('https://fcm.googleapis.com:8443/fcm/send/abc')
  or study_private.push_host_ok('https://push.apple.com.evil.org/x/abcdef')
  or study_private.push_host_ok('https://xpush.apple.com/abcdefghijkl')
  or study_private.push_host_ok('https://fcm.googleapis.com/a b c d e f')
  or coalesce(study_private.push_host_ok(null), false)),
  'refused: http, another host, a look-alike suffix, a user, a port, a space, nothing');
